input.text:
const r = await fetch('https://api.sendgrid.com/v3/campaigns?limit=20', {credentials:'include'});
const j = await r.json();
(j.result||[]).map(c=>({id:c.id,title:c.title,status:c.status,send_at:c.send_at,subject:(c.subject||'').slice(0,60)}))

