const urls = [
 'https://api.sendgrid.com/v3/campaigns/22625859/stats',
 'https://api.sendgrid.com/v3/marketing/legacy/campaigns/22625859/stats',
 'https://api.sendgrid.com/v3/marketing/stats/singlesends?singlesend_ids=22625859',
 'https://api.sendgrid.com/v3/campaigns/22625859'
];
const out = {};
for (const u of urls) {
  try { const r = await fetch(u,{credentials:'include'}); out[u] = [r.status, (await r.text()).slice(0,400)]; }
  catch(e){ out[u] = ['ERR', String(e)]; }
}
out

