input.text:
const ids=[22621835,22624323,22625856,22625857,22625858,22625859];
const out={};
for(const id of ids){const r=await fetch('https://api.sendgrid.com/v3/campaigns/'+id,{credentials:'include'});const j=await r.json();out[id]={title:j.title,cats:j.categories,lists:j.list_ids,segs:j.segment_ids,sender:j.sender_id,status:j.status};}
const c=await fetch('https://api.sendgrid.com/v3/categories?limit=200',{credentials:'include'}).then(r=>r.json());
({campaigns:out, categories:(Array.isArray(c)?c.map(x=>x.category):c)})

