  const r=await fetch('https://api.sendgrid.com/v3/messages/'+encodeURIComponent(m.msg_id),{credentials:'include'});
  if(r.status!==200){ errs.push(r.status); await new Promise(x=>setTimeout(x,1500)); continue; }
  const d=await r.json();
  for(const e of d.events||[]){
    if(e.event_name==='click'){ const u=(e.url||'(none)').split('?')[0]; urls[u]=(urls[u]||0)+1; events.push(e.processed.slice(0,16)+' '+u.slice(0,60)); }
  }
  await new Promise(x=>setTimeout(x,1500));
}
({urls, n_events:events.length, events:events.slice(0,30), errs})

