const clicked=Object.values(window.__n).filter(m=>m.clicks_count>0);
const perUrlPeople={}; const perUrlEvents={}; let noOpenButClicked=0;
for(const m of clicked){
  if(m.opens_count===0) noOpenButClicked++;
  const r=await fetch('https://api.sendgrid.com/v3/messages/'+encodeURIComponent(m.msg_id),{credentials:'include'});
  if(r.status!==200){ await new Promise(x=>setTimeout(x,1500)); continue; }
  const d=await r.json(); const seen=new Set();
  for(const e of d.events||[]){ if(e.event_name!=='click') continue; const u=(e.url||'').split('?')[0]; perUrlEvents[u]=(perUrlEvents[u]||0)+1; seen.add(u); }
  for(const u of seen) perUrlPeople[u]=(perUrlPeople[u]||0)+1;
  await new Promise(x=>setTimeout(x,1400));
}
({clickers:clicked.length, noOpenButClicked, perUrlPeople, perUrlEvents})

